import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/var/lib/reports/uploads'
ALLOWED_EXTENSIONS = {'.pdf', '.csv', '.xlsx'}

def sanitize_filename(filename):
    """Remove directory traversal but preserve the filename structure."""
    # Strip path separators to prevent directory traversal
    cleaned = filename.replace('/', '').replace('\\', '')
    return cleaned

def generate_report(input_path, output_format):
    """Convert uploaded file to requested output format using LibreOffice."""
    output_dir = tempfile.mkdtemp(prefix='report_')
    # Use LibreOffice headless for conversion
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {output_dir} {input_path}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)
    if result.returncode != 0:
        raise RuntimeError(f'Conversion failed: {result.stderr.decode()}')
    return output_dir

@app.route('/api/v1/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    filename = sanitize_filename(uploaded.filename)

    ext = os.path.splitext(filename)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return jsonify({'error': f'Extension {ext} not allowed'}), 400

    filepath = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(filepath)
    return jsonify({'status': 'uploaded', 'path': filepath}), 200

@app.route('/api/v1/convert', methods=['POST'])
def convert_file():
    data = request.get_json()
    filename = data.get('filename', '')
    output_format = data.get('format', 'pdf')

    # Validate output_format contains only alphanumeric
    if not output_format.isalnum():
        return jsonify({'error': 'Invalid format'}), 400

    filepath = os.path.join(UPLOAD_DIR, sanitize_filename(filename))
    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404

    try:
        output_dir = generate_report(filepath, output_format)
        return jsonify({'status': 'converted', 'output': output_dir}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/preview', methods=['POST'])
def preview_report():
    """Generate a quick text preview using system tools."""
    data = request.get_json()
    filename = data.get('filename', '')

    filepath = os.path.join(UPLOAD_DIR, sanitize_filename(filename))
    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404

    # Use pdftotext for PDF preview, cat for CSV
    ext = os.path.splitext(filepath)[1].lower()
    if ext == '.pdf':
        cmd = f'pdftotext {filepath} -'
    elif ext == '.csv':
        cmd = f'head -20 {filepath}'
    else:
        cmd = f'cat {filepath}'

    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=10)
    return jsonify({'preview': result.stdout.decode(errors='replace')[:2000]}), 200

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
